const input = $input.first().json;
const raw = input.raw && typeof input.raw === 'object' ? input.raw : input;
const customer = raw.customer && typeof raw.customer === 'object' ? raw.customer : {};
const order = raw.order && typeof raw.order === 'object' ? raw.order : {};
const message = raw.message && typeof raw.message === 'object' ? raw.message : {};

const reasons = [];
const text = typeof message.text === 'string' ? message.text.trim() : '';
const channelRaw = typeof message.channel === 'string' ? message.channel.trim() : '';
const customerId = typeof customer.id === 'string' ? customer.id.trim() : '';
const customerName = typeof customer.name === 'string' ? customer.name.trim() : '';
const emailRaw = typeof customer.email === 'string' ? customer.email.trim() : '';
const phoneRaw = typeof customer.phone === 'string' ? customer.phone.trim() : '';
const orderId = typeof order.id === 'string' ? order.id.trim() : '';

if (!text) reasons.push('message.text is required');
if (!channelRaw) reasons.push('message.channel is required');
if (!customerName) reasons.push('customer.name is required');
if (!customerId) reasons.push('customer.id is required');

if (customerId === '') {
  // already captured
} else if (customerId.length < 1) {
  reasons.push('customer.id is invalid');
}

if (emailRaw) {
  const emailOk = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(emailRaw);
  if (!emailOk) reasons.push('customer.email is invalid');
}

let phone = '';
if (phoneRaw) {
  phone = phoneRaw.replace(/[^0-9+]/g, '');
  const digits = phone.replace(/\D/g, '');
  if (digits.length < 8 || digits.length > 15) reasons.push('customer.phone is invalid');
}

if (order.id !== undefined && order.id !== null && order.id !== '' && !orderId) {
  reasons.push('order.id is invalid');
}

const now = $now;
const ymd = now.toFormat('yyyyMMdd');
const hms = now.toFormat('HHmmss');
const eventFromPayload = raw.event_id || raw.message_id || message.id || '';
const event_id = String(eventFromPayload || ('EVT-' + ymd + '-' + hms + '-' + Math.floor(Math.random() * 90 + 10)));
const conversationFromPayload = raw.conversation_id || '';
const conversation_id = String(conversationFromPayload || ('CONV-' + (customerId || 'anon') + '-' + ymd));
const ticket_id = 'SUP-' + ymd + '-' + hms;

const fullText = text;
const llmText = fullText.length > 8000 ? fullText.slice(0, 8000) : fullText;

return [{
  json: {
    is_valid: reasons.length === 0,
    validation_reason: reasons[0] || '',
    event_id,
    ticket_id,
    conversation_id,
    received_at: input.received_at || now.toISO(),
    customer_id: customerId,
    customer_name: customerName,
    customer_email: emailRaw.toLowerCase(),
    customer_phone: phone,
    customer_language: typeof customer.language === 'string' ? customer.language.trim() : '',
    order_id: orderId,
    order_status: order.status || '',
    order_value: order.value ?? '',
    order_currency: order.currency || '',
    order_expected_delivery: order.expected_delivery || '',
    channel: channelRaw.toLowerCase(),
    message_text: fullText,
    message_text_llm: llmText,
    is_duplicate: false,
    customer_record: null,
    conversation_history: [],
    order_record: null,
    policy_record: null,
    limited_context: false
  }
}];

const base = $('Validate And Normalize').first().json;
const row = $input.first().json || {};
const lookedUp = row.event_id !== undefined && row.event_id !== null && String(row.event_id) !== '';
const isDup = lookedUp && String(row.event_id) === String(base.event_id);
return [{ json: { ...base, is_duplicate: isDup } }];

const base = $('Merge Duplicate Check').first().json;
const rows = $input.all().map(i => i.json).filter(j => j && (j.ticket_id || j.message || j.intent || j.conversation_id));
return [{ json: { ...base, conversation_history: rows } }];

const base = $('Merge History Context').first().json;
const row = $input.first().json || {};
const found = !!(row.customer_id && String(row.customer_id) === String(base.customer_id));
return [{ json: {
  ...base,
  customer_record: found ? row : null,
  limited_context: !found,
  customer_tier: found ? (row.tier || '') : '',
  lifetime_value: found ? (row.lifetime_value || 0) : 0,
  previous_tickets: found ? (row.previous_tickets || 0) : 0
} }];

