const ctx = $('Merge Customer Context').first().json;
const ai = $input.first().json || {};
const output = ai.output && typeof ai.output === 'object' ? ai.output : ai;
const allowedIntents = ['order_status','delivery_issue','return_request','refund_request','exchange_request','cancellation','payment_issue','product_question','account_issue','complaint','general_question','unknown'];
let intent = String(output.intent || 'unknown');
if (!allowedIntents.includes(intent)) intent = 'unknown';
const tier = String(ctx.customer_tier || '').toLowerCase();
const ltv = Number(ctx.lifetime_value || 0);
let customer_priority = 'standard';
if (tier === 'vip') customer_priority = 'vip';
else if (['gold','premium','high'].includes(tier) || ltv >= 1000) customer_priority = 'high';

const text = String(ctx.message_text || '').toLowerCase();
const askingPolicy = /\b(policy|policies|how long|what is your|what are your|do you (accept|allow|offer)|how does (a |the )?return)\b/.test(text);
const requestingAction = /\b(i want to|please (return|refund|cancel|exchange)|process my|refund me|send it back|i was charged|charged twice)\b/.test(text);
let required_context = String(output.required_context || 'none');
let resolution_type = String(output.resolution_type || 'human_escalation');
let requires_human = output.requires_human === true || output.requires_human === 'true';

if (askingPolicy && !requestingAction) {
  if (/\breturn\b/.test(text)) required_context = 'return_policy';
  else if (/\brefund\b/.test(text)) required_context = 'refund_policy';
  else if (/\bship|deliver/.test(text)) required_context = 'shipping';
  else if (/\bpay|billing|charge/.test(text)) required_context = 'payment_policy';
  else if (/\baccount\b/.test(text)) required_context = 'account_policy';
  else if (/\bproduct|color|size|exchange/.test(text)) required_context = 'product_faq';
  if (['return_request','refund_request','exchange_request'].includes(intent)) intent = 'general_question';
  resolution_type = 'auto_resolve';
  requires_human = false;
}

let context_branch = 'none';
if (['payment_policy','account_policy'].includes(required_context)) {
  context_branch = 'other_policy';
} else if (askingPolicy && !requestingAction && ['product_faq','return_policy','refund_policy','shipping'].includes(required_context)) {
  context_branch = 'policy_only';
} else if (['refund_policy','return_policy'].includes(required_context)) {
  context_branch = 'order_and_policy';
} else if (['order','shipping'].includes(required_context)) {
  context_branch = 'order';
} else if (['product_faq'].includes(required_context)) {
  context_branch = 'policy_only';
}

const aiFailed = !output.intent && !output.internal_summary;
return [{ json: {
  ...ctx,
  intent,
  category: output.category || 'unknown',
  sentiment: output.sentiment || 'neutral',
  urgency: askingPolicy && !requestingAction ? 'low' : (output.urgency || 'medium'),
  customer_priority,
  required_context,
  context_branch,
  resolution_type,
  confidence: Number(output.confidence ?? 0),
  requires_human,
  customer_response: '',
  internal_summary: output.internal_summary || '',
  recommended_action: output.recommended_action || '',
  root_cause: output.root_cause || '',
  ai_error: aiFailed
} }];

const base = $('Overwrite Customer Priority').first().json;
function rowFrom(name) {
  try {
    const n = $(name);
    if (!n || !n.first()) return null;
    const j = n.first().json || {};
    if (j.order_id || j.category || j.policy || j.status) return j;
    return null;
  } catch (e) {
    return null;
  }
}
const order_record = rowFrom('Load Order') || rowFrom('Load Order For Policy');
const policy_record = rowFrom('Load Policy FAQ') || rowFrom('Load Refund Return Policy') || rowFrom('Load Other Policy');
const actionIntents = ['order_status','delivery_issue','return_request','refund_request','exchange_request','cancellation'];
const needsOrder = actionIntents.includes(base.intent) && base.context_branch !== 'policy_only';
const missingOrder = needsOrder && !base.order_id && !order_record;
const needsPolicy = ['product_faq','refund_policy','return_policy','payment_policy','account_policy'].includes(base.required_context) || base.context_branch === 'policy_only';
return [{ json: {
  ...base,
  order_record,
  policy_record,
  missing_order: missingOrder,
  missing_policy: needsPolicy && !(policy_record && policy_record.policy)
} }];

const d = $input.first().json;
const autoAllow = ['general_question','product_question','order_status','account_issue'];
const msg = String(d.message_text || '').toLowerCase();
const legal = /lawyer|legal action|sue|attorney|court/.test(msg);
const safety = /injury|injured|unsafe|hazard|fire|allergic/.test(msg);
const dispute = ['refund_request','payment_issue'].includes(d.intent);
const angry = d.sentiment === 'critical' || d.urgency === 'critical';
const vipComplaint = d.customer_priority === 'vip' && (d.intent === 'complaint' || angry || dispute);
const highValue = Number(d.lifetime_value || 0) >= 1000 && d.intent === 'complaint';
const policyReady = !!(d.policy_record && d.policy_record.policy);
const isPolicyFaq = d.context_branch === 'policy_only' || (policyReady && autoAllow.includes(d.intent));
const confidence = Number(d.confidence || 0);
const calm = d.sentiment !== 'critical' && d.urgency !== 'critical' && d.sentiment !== 'negative';

let route = 'human_escalation';
let reason = 'default_escalation';
if (d.ai_error) { route = 'human_escalation'; reason = 'ai_error'; }
else if (d.intent === 'unknown' && !isPolicyFaq) { route = 'human_escalation'; reason = 'unknown_intent'; }
else if (confidence < 0.75 && !isPolicyFaq) { route = 'human_escalation'; reason = 'low_confidence'; }
else if (d.urgency === 'critical' || d.sentiment === 'critical') { route = 'human_escalation'; reason = 'critical'; }
else if (legal || safety) { route = 'human_escalation'; reason = 'policy_safety'; }
else if (vipComplaint || highValue) { route = 'human_escalation'; reason = 'priority_complaint'; }
else if (dispute && (angry || d.sentiment === 'negative')) { route = 'human_escalation'; reason = 'dispute'; }
else if (isPolicyFaq && policyReady && calm) {
  route = 'auto_resolve';
  reason = 'policy_faq';
} else if (d.requires_human && !isPolicyFaq) {
  route = 'human_escalation';
  reason = 'requires_human';
} else if (d.missing_order) {
  route = 'need_information';
  reason = 'missing_order';
} else if (d.missing_policy && !policyReady) {
  route = 'need_information';
  reason = 'missing_policy';
} else if ((d.resolution_type === 'auto_resolve' || autoAllow.includes(d.intent)) && confidence >= 0.75 && calm && !dispute) {
  route = 'auto_resolve';
  reason = 'auto_allowlist';
} else if (d.resolution_type === 'need_information') {
  route = 'need_information';
  reason = 'need_information';
} else {
  route = 'human_escalation';
  reason = 'not_auto_eligible';
}

const statusMap = { auto_resolve: 'auto_resolved', need_information: 'need_information', human_escalation: 'escalated' };
return [{ json: { ...d, route, decision_reason: reason, status: d.ai_error ? 'ai_error' : statusMap[route] } }];

