const base = $('Apply Decision Rules').first().json;
const ai = $input.first().json || {};
const parsed = ai.output && typeof ai.output === 'object' ? ai.output : ai;
let customer_response = parsed.customer_response || parsed.text || parsed.output || '';
if (typeof customer_response !== 'string') customer_response = JSON.stringify(customer_response);
const policyText = base.policy_record && base.policy_record.policy ? String(base.policy_record.policy) : '';
if (base.route === 'auto_resolve') {
  if (!customer_response || customer_response.length < 5 || /escalat/i.test(customer_response)) {
    const name = base.customer_name || 'there';
    customer_response = policyText
      ? ('Hi ' + name + ', ' + policyText)
      : ('Hi ' + name + ', I can help with that. Please see the policy details we have on file, or share a bit more about what you need.');
  }
} else if (!customer_response || customer_response.length < 5) {
  if (base.route === 'need_information') {
    customer_response = 'Hi ' + (base.customer_name || 'there') + ', could you share your order ID so I can look this up?';
  } else {
    customer_response = 'Hi ' + (base.customer_name || 'there') + ', we received your request (ticket ' + base.ticket_id + '). A support teammate will follow up shortly.';
  }
}
return [{ json: { ...base, customer_response } }];

