const rows = $input.all().map(i => i.json).filter(r => r && r.status !== 'operations_report' && r.ticket_id && !String(r.ticket_id).startsWith('DAILY-'));
const now = $now;
const cutoff = now.minus({ hours: 24 }).toISO();
const day = rows.filter(r => {
  const ts = r.timestamp || r.received_at || '';
  return !ts || ts >= cutoff;
});
const total = day.length;
const auto_resolved = day.filter(r => r.status === 'auto_resolved' || r.resolution_type === 'auto_resolve').length;
const human_escalations = day.filter(r => r.status === 'escalated' || r.resolution_type === 'human_escalation').length;
const critical = day.filter(r => r.urgency === 'critical' || r.sentiment === 'critical').length;
const intents = {};
for (const r of day) {
  const k = r.intent || 'unknown';
  intents[k] = (intents[k] || 0) + 1;
}
const top_issues = Object.entries(intents).sort((a,b) => b[1]-a[1]).slice(0,5).map(([label, count]) => ({ label, count, pct: total ? Math.round(count * 1000 / total) / 10 : 0 }));
return [{ json: { total, auto_resolved, human_escalations, critical, top_issues, report_date: now.toFormat('yyyy-MM-dd'), ticket_id: 'DAILY-' + now.toFormat('yyyyMMdd') } }];

